We define the \emph{defect}\, operator $ D_m(t) $ of $ S_m(t) $ by
\begin{equation*}
D_m(t) = \sca\,\Opgen\,S_m(t) - S_m'(t) \in \mathbb C^{n \times n}.

\label{prop:prop3}
\noindent
For any $ A \in \mathbb C^{\tjnew{n \times n}} $
the error $ L_m(t)v $ satisfies the asymptotic relation
\begin{equation} \label{asy-leading}
L_m(t)v = \tau_{m+1,m}\gamma_m\,\frac{(\sca\,t)^{m}}{m!}v_{m+1} + R_{m+1}(t),
\quad R_{m+1}(t) = {\mathcal{O}}(t^{m+1}),
\end{equation}
for $ t \to 0 $.

Taylor expansion. Due to $ L_m(t)v = {\mathcal{O}}(t^m) $, \tjnew{see~\eqref{orderofDmLm},}
\begin{equation}\label{prop-3-proof}
\begin{aligned}
&L_m(t)v = E(t)v - S_m(t)v
= \frac{(\sca\,t)^m}{{m!}}(\Opgen^m v - V_m T_m^m\,e_1) + R_{m+1}(t),\\
&\text{with Taylor remainder}~~ R_{m+1}(t) = {\mathcal{O}}(t^{m+1}).
\end{aligned}
\end{equation}
Multiplying the
identity~\tjnew{{\eqref{HVTm}} (with $ j = m-1 $) by $ A $} and using~\eqref{krylovidentity} gives
\begin{align*}
\Opgen^m\,v
&= \Opgen\,V_m T_m^{m-1} e_1
 = (V_m T_m + \tau_{m+1,m}\,v_{m+1} e_m^\ast) T_m^{m-1} e_1 \\
&= V_m T_m^m\,e_1 + \tau_{m+1,m}\, (e_m^\ast\,T_m^{m-1} e_1)\,v_{m+1}
 = V_m T_m^m\,e_1 + \tau_{m+1,m} \gamma_m v_{m+1},
\end{align*}
whence~\eqref{prop-3-proof} simplifies to~\eqref{asy-leading}. \qed


                    \label{prop:prop1}

\noindent
Let $T_m \in \mathbb C^{m\times m}$ be an upper Hessenberg matrix with eigenvalues $ \lambda_1,\ldots,\lambda_m $
and $ \text{spec}(\sca T_m) \subseteq \mathbb C_- $.
Then the function $ \delta_m(t) $ defined as in~\eqref{defdelta}, i.e.,
\begin{equation*}
\delta_m(t) = e_m^\ast\,{\rm e}^{\sca\,t\,T_m}e_1
            = \big( {\rm e}^{\sca\,t\,T_m} \big)_{m,1},
\end{equation*}
satisfies
\begin{equation}\label{deltam-repr}
\delta_m(t) =
\divdif{\lambda_1,\ldots,\lambda_m}{f_t} \gamma_m
\leq {\frac{t^{m-1}}{(m-1)!}\,\gamma_m,}
\end{equation}
with $ \gamma_m $ from~\eqref{gammam} and
where $\divdif{\lambda_1,\ldots,\lambda_m}{f_t}$ is
the {$ (m-1) $-th} divided difference over
$ \text{\rm spec}(T_m) $
of the function $ f_t $ defined in~\eqref{def:thetadd}.

We proceed from the Newton representation of the
interpolant $p_t(\lambda) $ from~\eqref{pt},
\begin{equation*}
p_t(\lambda) = \sum_{j=0}^{m-1}
               \divdif{\lambda_1,\ldots,\lambda_{j+1}}{f_t}\,\omega_j(\lambda),
\end{equation*}
with
$ \omega_j(\lambda) = (\lambda-\lambda_1) \cdots (\lambda-\lambda_{j}) $.

{From~\eqref{eTe} and by definition of $ \gamma_m $, 
it is obvious that the $ \omega_j $ satisfy}
\begin{equation*}
e_m^\ast\,\omega_j(T_m)\,e_1 =
\left\{\begin{array}{ll}
0,       & j=0,\ldots,m-2, \\
\gamma_m,& j=m-1.
\end{array}\right.
\end{equation*}
Together with~\eqref{pt} this shows that the identity claimed
in~\eqref{deltam-repr} is valid:
\begin{equation*}
\delta_m(t)
= e_m^\ast\,{\rm e}^{\sca\,t T_m}\,e_1
= e_m^\ast\,p_t(T_m) e_1
= \sum_{j=0}^{m-1} \divdif{\lambda_1,\ldots,\lambda_{j+1}}{f_t} e_m^\ast\,\omega_j(T_m)e_1
= \divdif{\lambda_1,\ldots,\lambda_m}{f_t} \gamma_m.
\end{equation*}
