\label{theorem:upperboundexp}

\noindent
For the nonexpansive case the error $ L_m(t)v $ of the Krylov approximation~\eqref{Smv}
to $ E(t)v $ satisfies
\begin{equation} \label{asyerrest}
\| L_m(t)v \|_2 \leq \tau_{m+1,m}\gamma_m\,\frac{t^{m}}{m!}
\end{equation}
with $ \tau_{m+1,m} $ from~\eqref{krylovidentity} and
$ \gamma_m $ from~\eqref{gammam}.

We proceed from~\eqref{errestintdefect}.
For $ \delta_m $ defined in~\eqref{defdelta},
Proposition~\ref{prop:prop1} implies
\begin{equation*}
|\delta_m(s)|



\leq \frac{s^{m-1}}{(m-1)!} \gamma_m,
\end{equation*}
and this gives an upper bound for the error
integral~\eqref{errorapprox1}:
\begin{equation*}
\|L_m(t)v\|_2 \leq

\tau_{m+1,m} \gamma_m \int_0^t \frac{s^{m-1}}{(m-1)!}\,\mathrm{d} s
= \tau_{m+1,m}\gamma_m \frac{t^{m}}{m!},
\end{equation*}
which completes the proof. 
\tjnew{
Proposition~\ref{prop:prop1} is applied here in the nonexpansive case ($ W(\sigma A) \subseteq \mathbb C_- $)
which implies the requirement $ \text{spec}(\sca T_m) \subseteq \mathbb C_- $, see~\eqref{subsetofspectrum}.}

\qed

\label{prop:prop4}

\noindent
The upper bound~\eqref{asyerrest} is asymptotically correct
for $ t \to 0 $, i.e.,
\begin{equation} \label{asyerrcorr}
\| L_m(t)v \|_2 = \tau_{m+1,m}\gamma_m\,\frac{t^m}{m!} + {\mathcal{O}}(t^{m+1}).
\end{equation}

\label{theorem:upperboundphi}
The error of the Krylov approximation~\eqref{kry-phi}
to $ \phif_p(\sca\,t \Opgen)v $ with $ p \geq 0 $ satisfies
\begin{subequations}
\begin{equation}\label{leadingtermphij}
L^p_m(t)v = \tau_{m+1,m}\,\gamma_m \frac{(\sca\, t)^m}{(m+p)!} \, v_{m+1} + \mathcal{O}(t^{m+1}).
\end{equation}
Furthermore, \tjnew{in the nonexpansive case} its norm is bounded by
\begin{equation}\label{eresphij}
\|L^p_m(t)v \|_2  \leq   \tau_{m+1,m}\,\gamma_m\,\frac{t^{m}}{(m+p)!},
\end{equation}
\end{subequations}
and this bound is asymptotically correct for $ t \to 0 $.

For $p=0$ the result directly follows from Propositions~\ref{prop:prop3},~\ref{prop:prop4} and Theorem~\ref{theorem:upperboundexp}. We now assume $ p \geq 1 $.
Via the series representation~\eqref{defphiseries} of $\phif_p$
we can determine the leading term of the error in an analogous way
as in Proposition~\ref{prop:prop3}:
\begin{align*}
\phif_p(\sca\,t \Opgen)v -  V_m \phif_p(\sca\,t T_m) e_1
&= \frac{(\sca\,t)^m \,(A^m v - V_m T_m^m e_1)}{(m+p)!} + \mathcal{O}(t^{m+1}) \\

&= \tau_{m+1,m}\,\gamma_m \frac{(\sca\, t)^m}{(m+p)!} \, v_{m+1} + \mathcal{O}(t^{m+1}),
\end{align*}
which proves~\eqref{leadingtermphij}.

Furthermore, proceeding from~\eqref{defphiint} we obtain
\begin{align*}
\phif_p(\sca\,t \Opgen)v - V_m \phif_p(\sca\,t T_m) e_1
&= \frac{1}{(p-1)!} \int_0^1 (1-\theta)^{p-1}\big( {\rm e}^{\sca\,\theta\,t \Opgen} v - V_m\,{\rm e}^{\sca\,\theta\,t T_m} e_1 \big) \,\mathrm{d} \theta\\
&= \frac{1}{(p-1)!} \int_0^1 (1-\theta)^{p-1} L_m(\theta\,t)v \,\mathrm{d} \theta,
\end{align*}
with the error $L_m(t)v$ for the matrix exponential case.
Now we apply Theorem~\ref{theorem:upperboundexp} to obtain
\begin{align*}
\| \phif_p(\sca\,t \Opgen)v - V_m \phif_p(\sca\,t T_m) e_1 \|_2
&\leq \frac{1}{(p-1)!} \int_0^1 (1-\theta)^{p-1}  \|L_m(\theta\,t)v\|_2 \,\mathrm{d} \theta\\
&\leq \tau_{m+1,m}\,\gamma_m\,\frac{t^m}{(p-1)!\,m!} \int_0^1 (1-\theta)^{p-1} \theta^m \,\mathrm{d} \theta\\
&= \tau_{m+1,m}\,\gamma_m\,\frac{t^{m}}{(m+p)!},
\end{align*}
which proves~\eqref{eresphij}. \qed
