\label{rmk:PhiAsymptoticCorrect}
From the representation~\eqref{defphiseries} for the $\phif_j$
together with~\eqref{eTe} and~\eqref{gammam} we observe
\begin{equation} \label{em-phi-e1}
\begin{aligned}
e_m^\ast \phif_j(\sca t T_m) e_1 &=

\frac{(\sca t)^{m-1} e_m^\ast T_m^{m-1}\,e_1}{(m-1+j)!}
+ \mathcal{O}(t^m)
= \gamma_m \,\frac{(\sca t)^{m-1}}{(m-1+j)!}
+ \mathcal{O}(t^m).
\end{aligned}
\end{equation}
By~\eqref{em-phi-e1} we observe $ e_m^\ast\phif_{j}(\sca\,tT_m)\,e_1 = \mathcal{O}(t^{m-1}) $ for $ j \geq 0 $
and we conclude that the asymptotically leading order term of $ L^p_m(t)v $ for $ t \to 0 $ is obtained by the leading term ($j=p+1$) of the series~\eqref{generalizeerrorSaadsum1}:
\begin{subequations}
\begin{equation}\label{Lpleadingtermsum}
L^p_m(t)v = \tau_{m+1,m} \sca\,t (e_m^\ast \phif_{p+1}(\sca\,t\,T_m) e_1 ) v_{m+1} + \mathcal{O}(t^m).
\end{equation}
Analogously we obtain the asymptotically leading order term of $ L^{p,+}_m(t)v $ for $ t \to 0 $ by the leading term ($j=p+2$) of the series~\eqref{generalizeerrorSaadsum2}:
\begin{equation}\label{Lpplusleadingtermsum}
L^{p,+}_m(t)v = \tau_{m+1,m} (\sca\,t)^2 (e_m^\ast \phif_{p+2}(\sca\,t\,T_m) e_1) \,\Opgen v_{m+1} + \mathcal{O}(t^{m+1}).
\end{equation}
\end{subequations}
The asymptotically leading terms in~\eqref{Lpleadingtermsum} and~\eqref{Lpplusleadingtermsum} can be used as error estimators:
\begin{subequations}
\begin{equation}\label{LPnextphierrorest}
\|L^p_m(t)v\|_2 \approx \tau_{m+1,m}\,t |e_m^\ast \phif_{p+1}(\sca\,t\,T_m) e_1|
\end{equation}
and
\begin{equation}\label{LPplusnextphierrorest}
\|L^{p,+}_m(t)v\|_2 \approx \|\Opgen v_{m+1}\|_2 \tau_{m+1,m}\,t^2 |e_m^\ast \phif_{p+2}(\sca\,t\,T_m) e_1|.
\end{equation}
\end{subequations}
The error estimators~\eqref{LPnextphierrorest} and~\eqref{LPplusnextphierrorest} are already suggested in \cite{sidje98,niewri12}.
We will refer to them as $\Erone$ in the context of the $\phif$-functions with standard and corrected Krylov approximation,
generalizing the corresponding quantities for the exponential case $p=0$.

\label{theorem:asymerrorpricorrected}
The error of the corrected Krylov approximation~\eqref{generalizeerrornotation2}
to $ \phif_p(\sca\,t \Opgen)v $ with $ p \geq 0 $ satisfies
\begin{subequations}
\begin{equation}\label{leadingtermphijcor}
L^{p,+}_m(t)v  = \tau_{m+1,m}\,\gamma_m \frac{(\sca\, t)^{m+1}}{(m+p+1)!} \, \Opgen v_{m+1} + \mathcal{O}(t^{m+2}).
\end{equation}
Furthermore, \tjnew{in the nonexpansive case} its norm is bounded by
\begin{equation}\label{eresphijcor}
\|L^{p,+}_m(t)v\|_2 \leq    \|\Opgen v_{m+1}\|_2\, \tau_{m+1,m}\,\gamma_m \frac{t^{m+1}}{(m+p+1)!},
\end{equation}
\end{subequations}
and this bound is asymptotically correct for $ t \to 0 $.

Applying~\eqref{em-phi-e1} (with $j=p+2$) to~\eqref{Lpplusleadingtermsum} shows~\eqref{leadingtermphijcor}:
\begin{equation*}
L^{p,+}_m(t)v = \tau_{m+1,m}\, \gamma_m\, \frac{(\sca\,t)^{m+1}}{(m+p+1)!} \,\Opgen v_{m+1} + \mathcal{O}(t^{m+2}).
\end{equation*}

From Proposition~\ref{prop:generalSaadsum} we observe
\begin{align*}
L^{p,+}_m(t)v = \sigma\,t\,\Opgen \,\,L^{p+1}_m(t)v.
\end{align*}
Using the integral representation analogously as in the proof of Theorem~\ref{theorem:upperboundphi} for $L^{p+1}_m(t)v$ and
formula~\eqref{LDint} for $L_m(t)v$, we obtain
\begin{align*}
L^{p,+}_m(t)v &= \sigma\,t\,\Opgen\,\, L^{p+1}_m(t)v = \tau_{m+1,m} \sigma\,t \frac{1}{p!} \int_0^1 (1-\theta)^{p} \Opgen\, L_m(\theta\,t)v \,\mathrm{d} \theta\\
&= \tau_{m+1,m} \sigma\,t \frac{1}{p!} \int_0^1 (1-\theta)^{p} \int_0^{\theta t} {\rm e}^{\sca (\theta t-s) \Opgen} \Opgen v_{m+1} \delta_m( s)\,\mathrm{d} s \,\mathrm{d} \theta.
\end{align*}
With norm inequalities \tjnew{(note the nonexpansive case)} and Proposition~\ref{prop:prop1} we obtain
\begin{align*}
\|L^{p,+}_m(t)v\|_2 &\leq \tau_{m+1,m} \,t\,\|\Opgen v_{m+1}\|_2 \frac{1}{p!} \int_0^1 (1-\theta)^{p} \int_0^{\theta t}  |\delta_m( s)|\,\mathrm{d} s \,\mathrm{d} \theta\\
&\leq \|\Opgen v_{m+1}\|_2 \tau_{m+1,m} \gamma_m\, t^{m+1}\,\frac{1}{p!\,m!} \int_0^1 (1-\theta)^{p} \theta ^m\,\mathrm{d} s \,\mathrm{d} \theta\\
&= \|\Opgen v_{m+1}\|_2  \tau_{m+1,m} \gamma_m \frac{t^{m+1}}{(m+p+1)!},
\end{align*}
which proves~\eqref{eresphijcor}. 
\tjnew{Proposition~\ref{prop:prop1} is applied here in the nonexpansive case,
see also the proof of Theorem \ref{theorem:upperboundexp}.}\hfill\qed

\label{upperboundphi}
\tjnew{For the nonexpansive case} with $\sca=1$ and \tjnew{a Hermitian} matrix $\Opgen$ we obtain
\begin{equation*}
|\delta_m(t)| = \delta_m(t) > 0 ~~~\text{for}~~t > 0.
\end{equation*}
This leads to the following upper bounds for the errors $L^p_m$ and $L^{p,+}_m$ with $p\geq 0$:
\begin{subequations}
\begin{equation}\label{hermitianphiestimate1}
\|L^p_m(t)v\|_2 \leq \tau_{m+1,m} \, t \, \underbrace{e_m^\ast \, \phif_{p+1}(tT_m) \, e_1}_{\geq\, 0}
\end{equation}
and
\begin{equation}\label{hermitianphiestimate2}
\|L^{p,+}_m(t)v\|_2 \leq \|\Opgen v_{m+1}\|_2 \,\tau_{m+1,m} \, t^2 \, \underbrace{e_m^\ast \, \phif_{p+2}(tT_m) \, e_1}_{\geq\, 0}.
\end{equation}
\end{subequations}

For \tjnew{a Hermitian} matrix $\Opgen$ we obtain a symmetric, tridiagonal matrix $T_m$ with distinct, real eigenvalues via Lanczos approximation, see~\cite[Chap. 3.1]{horn85}.
By Proposition~\ref{prop:prop1} we observe
\begin{equation*}
\delta_m(t) = \divdif{\lambda_1,\ldots,\lambda_m}{f_t} \gamma_m
\end{equation*}
with $f_t(\lambda)={\rm e}^{t\,\lambda}$ for the case $\sca=1$.
For divided differences of real-valued functions over real nodes we obtain $\divdif{\lambda_1,\ldots,\lambda_m}{f_t} \in \mathbb R$ and
\begin{equation}\label{ddreal}
\divdif{\lambda_1,\ldots,\lambda_m}{f_t} = \frac{D^{(m-1)} f_t(\xi)}{(m-1)!} = \frac{t^{m-1} {\rm e}^{t\xi}}{(m-1)!}~~~\text{for}~~\xi\in[\lambda_1,\lambda_m].
\end{equation}
Equation~\eqref{ddreal} shows $\divdif{\lambda_1,\ldots,\lambda_m}{f_t} > 0$ and with $\gamma_m > 0 $ we conclude
\begin{equation*}
\delta_m(t) > 0,~~~\text{and}~~~|\delta_m(t)|=\delta_m(t).
\end{equation*}
We continue with~\eqref{hermitianphiestimate1} in the case $p=0$:
\begin{equation*}
\|L_m(t)v\|_2\leq \tau_{m+1,m} \int_0^t |\delta_m(s)|\,\mathrm{d} s = \tau_{m+1,m} \int_0^t e_m^\ast\,{\rm e}^{sT_m} \,e_1 \,\mathrm{d} s = \tau_{m+1,m} t \, e_m^\ast \, \phif_1(tT_m) \, e_1.
\end{equation*}
For the case $p \geq 1$ we start analogously to Theorem~\ref{theorem:upperboundphi}.
Using definition~\eqref{defphiint} for the $\phif$-functions
and resorting to the case $p=0$ we find
\begin{align*}
\| L_m^p(t)v \|_2
&= \frac{1}{(p-1)!} \int_0^1 (1-\theta)^{p-1}  \|L_m(\theta\,t)v\|_2 \,\mathrm{d} \theta\\
&\leq \tau_{m+1,m}\,t\,\frac{1}{(p-1)!} \int_0^1 (1-\theta)^{p-1} \theta \, e_m^\ast \, \phif_1(\theta\,t\,T_m) \, e_1  \,\mathrm{d} \theta.
\end{align*}
Evaluation of the integral yields
\begin{equation}\label{partofproofphicor1}
\begin{aligned}
\| L_m^p(t)v \|_2
&\leq \tau_{m+1,m}\,t\,\frac{1}{(p-1)!} \int_0^1 (1-\theta)^{p-1} \theta \, e_m^\ast \, \phif_1(\theta\,t\,T_m) \, e_1  \,\mathrm{d} \theta\\
&= \tau_{m+1,m}\,t\,\sum_{k=0}^{\infty}\frac{e_m^\ast \,(\,t\,T_m)^k \, e_1}{(p-1)!\,(k+1)!} \int_0^1 (1-\theta)^{p-1} \theta^{k+1} \,     \,\mathrm{d} \theta \\
&= \tau_{m+1,m}\,t\,\sum_{k=0}^{\infty} \frac{e_m^\ast \,(\,t\,T_m)^k \, e_1}{(p+k+1)!}\\
&= \tau_{m+1,m}\,t\,e_m^\ast \phif_{p+1}(\,t\,T_m) \, e_1.
\end{aligned}
\end{equation}
This shows~\eqref{hermitianphiestimate1}.
To show~\eqref{hermitianphiestimate2} we start analogously to Theorem~\ref{theorem:asymerrorpricorrected}:
\begin{equation*}
\|L^{p,+}_m(t)v\|_2 = \|t\,\Opgen\,L^{p+1}_m(t)v\|_2 \leq \|\Opgen v_{m+1}\|_2\,\tau_{m+1,m} \,t\, \frac{1}{p!} \int_0^1 (1-\theta)^{p} \int_0^{\theta t}  |\delta_m( s)|\,\mathrm{d} s \,\mathrm{d} \theta.
\end{equation*}
Using $|\delta_m(s)|=\delta_m(s)$ and evaluating the inner integral by the $\phif_1$ function, we obtain
\begin{equation*}
\|L^{p,+}_m(t)v\|_2 \leq \|\Opgen v_{m+1}\|_2\,\tau_{m+1,m}\,t^2\,\frac{1}{p!} \int_0^1 (1-\theta)^{p} \theta \, e_m^\ast \, \phif_1(\theta\,t\,T_m) \, e_1  \,\mathrm{d} \theta.
\end{equation*}
Evaluation of the integral analogously to~\eqref{partofproofphicor1},
\begin{equation*}
\|L^{p,+}_m(t)v\|_2 \leq \|\Opgen v_{m+1}\|_2\,\tau_{m+1,m}\,t^2\,e_m^\ast \phif_{p+2}(\,t\,T_m) \, e_1,
\end{equation*}
completes the proof. \hfill\qed

\label{remark:quadnew}
With $\rho(0+)=m-1$ and the assumptions that the effective order is slowly decreasing locally at $t=0$ and sufficiently smooth,
we suggest choosing $\tilde{m}=\rho(t)$ for a step of size $t$ \tjnew{to} improve the quadrature based estimate.
\begin{equation}\label{eq:effoquad}
\|L_m(t)v\|_2 \leq \tau_{m+1,m} \int_0^t |\delta_m(s)| \, \mathrm{d} s \approx \tau_{m+1,m} \tfrac{t}{\rho(t)+1} \,|\delta_m(t)|,
\end{equation}
We will refer to this as \emph{effective order quadrature} estimate.
In the limit $t\to0$ this choice of quadrature is equivalent to the Hermite quadrature and, therefore, asymptotically correct.

